// Generator: manifest entries -> TypeScript wrappers (contracts/V8HOST.md).
import path from "node:path";
import { RustManifestEntry, groupByModule } from "./manifest.js";
import { objectFields, validatorToTs } from "./validators.js";

export const GENERATED_HEADER = "// @generated by convex-rust. Do not edit.";

export interface GenerateOptions {
  entries: RustManifestEntry[];
  /** File name of the wasm below `<out>/_wasm/`, e.g. `hello_rust.wasm`. */
  wasmFile: string;
  /**
   * Directory of the generated files, relative to the Convex functions
   * directory, with `/` separators (default `rust`).
   */
  outRelToFunctions?: string;
  /**
   * Short content hash of the wasm, written into each module. `convex dev` does not watch
   * `.wasm` imports, so this makes a wasm-only change touch a watched `.ts` file.
   */
  wasmHash?: string;
  /** Environment variable names the guest may read (`build --env`). */
  env?: string[];
  /**
   * Per-module wasm (`build --split`): Convex module name -> wasm file below `<out>/_wasm/` and its
   * content hash. Modules not listed use `wasmFile`.
   */
  moduleWasm?: Map<string, { file: string; hash: string }>;
}

/** Relative import specifier with a leading `./` or `../`, `/` separators. */
function rel(fromDir: string, to: string): string {
  const r = path.posix.relative(fromDir, to) || ".";
  return r.startsWith(".") ? r : `./${r}`;
}

function actionExport(e: RustManifestEntry, env: string[] = []): string {
  const builder = e.visibility === "internal" ? "internalAction" : "action";
  const lines: string[] = [`export const ${e.name} = ${builder}({`];
  const args = e.args as any;
  if (args !== null && args !== undefined) {
    if (args.type !== "object") {
      throw new Error(`${e.modulePath}::${e.name}: args validator must be an object`);
    }
    lines.push(`  args: ${objectFields(args.value)},`);
  }
  if (e.returns !== null && e.returns !== undefined) {
    lines.push(`  returns: ${validatorToTs(e.returns)},`);
  }
  const argType = args === null || args === undefined ? "args: any" : "args";
  lines.push(
    `  handler: (ctx, ${argType}) => runRust(ctx, wasm, ${JSON.stringify(`convex_run:${e.modulePath}:${e.name}`)}, args${env.length ? `, { env: ${JSON.stringify(env)} }` : ""}),`,
  );
  lines.push("});");
  return lines.join("\n");
}

const isHttp = (e: RustManifestEntry): boolean => e.kind === "http";

function httpExport(e: RustManifestEntry, env: string[] = []): string {
  return `export const ${e.name} = httpAction((ctx, request) => runRustHttp(ctx, wasm, ${JSON.stringify(`convex_run:${e.modulePath}:${e.name}`)}, request${env.length ? `, { env: ${JSON.stringify(env)} }` : ""}));`;
}

function usesValidators(entries: RustManifestEntry[]): boolean {
  return entries.some((e) => !isHttp(e) && (e.args != null || e.returns != null));
}

// Names the generated file itself uses, plus every ECMAScript reserved word (`export const delete` is a syntax error).
const RESERVED = new Set([
  "default", "runRust", "runRustHttp", "wasm", "action", "internalAction", "httpAction", "v",
  "await", "break", "case", "catch", "class", "const", "continue", "debugger", "delete", "do", "else",
  "enum", "export", "extends", "false", "finally", "for", "function", "if", "import", "in", "instanceof",
  "new", "null", "return", "super", "switch", "this", "throw", "true", "try", "typeof", "var", "void",
  "while", "with", "yield", "let", "static", "implements", "interface", "package", "private", "protected",
  "public", "arguments", "eval", "undefined", "NaN", "Infinity",
]);

/** Generated files, keyed by path relative to the out dir. */
export function generateFiles(opts: GenerateOptions): Map<string, string> {
  const out = (opts.outRelToFunctions ?? "rust").replace(/\\/g, "/").replace(/\/+$/, "");
  const files = new Map<string, string>();
  for (const [module, entries] of [...groupByModule(opts.entries)].sort(([a], [b]) =>
    a < b ? -1 : 1,
  )) {
    for (const e of entries) {
      if (!/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(e.name) || RESERVED.has(e.name)) {
        throw new Error(`Rust function ${e.modulePath}::${e.name} cannot be exported as a Convex function name.`);
      }
    }
    // File directory relative to the functions dir, e.g. `rust/a`.
    const fileDir = path.posix.join(out, path.posix.dirname(module));
    const toOut = (p: string) => rel(fileDir, path.posix.join(out, p));
    const toFunctions = (p: string) => rel(fileDir, p);
    const builders = [
      ...(entries.some((e) => !isHttp(e) && e.visibility !== "internal") ? ["action"] : []),
      ...(entries.some((e) => !isHttp(e) && e.visibility === "internal") ? ["internalAction"] : []),
      ...(entries.some(isHttp) ? ["httpAction"] : []),
    ];
    const mw = opts.moduleWasm?.get(module);
    const wasmFile = mw?.file ?? opts.wasmFile;
    const wasmHash = mw?.hash ?? opts.wasmHash;
    const head = [
      GENERATED_HEADER,
      ...(wasmHash ? [`// wasm: ${wasmHash}`] : []),
      `import { ${builders.join(", ")} } from "${toFunctions("_generated/server")}";`,
    ];
    if (usesValidators(entries)) head.push('import { v } from "convex/values";');
    const runtime = [...(entries.some((e) => !isHttp(e)) ? ["runRust"] : []), ...(entries.some(isHttp) ? ["runRustHttp"] : [])];
    head.push(`import { ${runtime.join(", ")} } from "convex-rust/runtime";`);
    head.push(`import wasm from "${toOut(`_wasm/${wasmFile}`)}";`);
    const body = [...entries].sort((a, b) => (a.name < b.name ? -1 : 1)).map((e) => (isHttp(e) ? httpExport(e, opts.env) : actionExport(e, opts.env)));
    files.set(`${module}.ts`, `${head.join("\n")}\n\n${body.join("\n\n")}\n`);
  }
  files.set(
    "_wasm.d.ts",
    `${GENERATED_HEADER}\ndeclare module "*.wasm" {\n  const m: WebAssembly.Module;\n  export default m;\n}\n`,
  );
  return files;
}
